#!/bin/sh
set -e
goal="Improve documentation with cover page"
echo "Plan:"
echo "1. Create a new cover.md file to serve as the cover page for the documentation."
echo "2. Update docsifyConfig.js to make cover.md as the landing page."
echo "3. Update styles.css to include styles corresponding to the logo colors for the cover page."

# Step 1: Create cover.md file with the main message and extensive use of logo colors.
cat > ./docs/cover.md << 'EOF'
# <span style="color:rgb(59, 130, 246);">You are the Pro,</span> <span style="color:rgb(253, 186, 116);">Junior</span> <span style="color:rgb(185, 28, 28);">codes</span>

Welcome to **Junior**, your AI-first IDE.

**Navigate through the following sections to know more:**
- [Getting Started](usage.md)
- [Open Jobs](open_jobs.md)
- [Roadmap](roadmap.md)

EOF

# Step 2: Update docsifyConfig.js to make cover.md the landing page
cat > ./docs/docsifyConfig.js << 'EOF'
window.$docsify = {
  name: 'Junior',
  repo: 'https://github.com/tisztamo/Junior',
  loadSidebar: true,
  autoHeader: true,
  logo: "assets/logo.svg",
  nameLink: 'https://github.com/tisztamo/Junior',
  homepage: 'cover.md'
}
EOF

# Step 3: Update styles.css to use logo colors extensively for the cover page
cat > ./docs/assets/styles.css << 'EOF'
.app-name-link img {
  max-width: 70px;
}

iframe {
  margin: 16px;
}

/* Adding logo colors to cover page */
.cover-color-1 {
  color: rgb(59, 130, 246);
}

.cover-color-2 {
  color: rgb(253, 186, 116);
}

.cover-color-3 {
  color: rgb(185, 28, 28);
}
EOF

echo "\033[32mDone: $goal\033[0m\n"

